using System.Diagnostics.CodeAnalysis;
using Fdw.Collections.Attributes;
using Fdw.Results;
using Fdw.Results.Abstractions;

namespace Fdw.Roslyn.Commands.Abstractions.Results;

/// <summary>
/// The caller explicitly named a compiler- or build-generated file.
/// </summary>
/// <remarks>
/// Skipping it silently would report "selector matched zero types", which is false and sends the caller
/// looking for a typo. The file matched; it is just not something that can be edited, because the next
/// build regenerates it.
/// </remarks>
[TypeOption(typeof(RoslynResultCodes), "SelectorMatchedGeneratedFile", RestrictToCurrentCompilation = true)]
[ExcludeFromCodeCoverage]
public sealed class SelectorMatchedGeneratedFileCode : RoslynResultCodeBase
{
    /// <summary>
    /// Initializes a new instance of the <see cref="SelectorMatchedGeneratedFileCode"/> class.
    /// </summary>
    public SelectorMatchedGeneratedFileCode()
        : base(31032, "SelectorMatchedGeneratedFile",
            ResultSeverities.ByName("Error"),
            "'{FilePath}' is generated by the build, so editing it would be discarded on the next compile. Remove it from the selection",
            isRetryable: false)
    {
    }
}
